package edu.uiu.aoop.careerforge.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="applications", uniqueConstraints=@UniqueConstraint(name="uq_application",columnNames={"user_id","job_id"})) public class JobApplication extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="job_id",nullable=false) private Job job;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private ApplicationStatus status=ApplicationStatus.applied; @Column(name="match_percentage") private Double matchPercentage; @Column(name="cover_letter",columnDefinition="LONGTEXT") private String coverLetter; @Column(name="resume_snapshot",columnDefinition="json") private String resumeSnapshot; @Column(name="resume_file_name") private String resumeFileName; @Column(name="resume_file_type") private String resumeFileType; @Column(name="resume_file_data",columnDefinition="LONGTEXT") private String resumeFileData; @Column(name="applied_at") private Instant appliedAt;
 protected JobApplication(){} public JobApplication(User student,Job job,Double match,String coverLetter,String snapshot,String resumeFileName,String resumeFileType,String resumeFileData){this.student=student;this.job=job;this.matchPercentage=match;this.coverLetter=coverLetter;this.resumeSnapshot=snapshot;this.resumeFileName=resumeFileName;this.resumeFileType=resumeFileType;this.resumeFileData=resumeFileData;this.appliedAt=Instant.now();} public Long getId(){return id;} public User getStudent(){return student;} public Job getJob(){return job;} public ApplicationStatus getStatus(){return status;} public Double getMatchPercentage(){return matchPercentage;} public Instant getAppliedAt(){return appliedAt;} public void transitionTo(ApplicationStatus next){ if(status==ApplicationStatus.withdrawn) throw new IllegalStateException("A withdrawn application cannot be changed"); status=next; }
}
